-- ============================================================================
-- PRICEHUNT 100-PRODUCT DATABASE SEED SCRIPT (IN RUPEES / â‚¹)
-- Multi-store coverage: Amazon India, Flipkart, Myntra, and AJIO
-- ============================================================================
USE pricehunt_db;

-- 1. Seed Platforms (Amazon, Flipkart, Myntra, AJIO, Croma, Reliance Digital)
ON DUPLICATE KEY UPDATE name=VALUES(name), website_url=VALUES(website_url);

-- 2. Seed Default Demo User
ON DUPLICATE KEY UPDATE email=VALUES(email);

-- 3. Seed 100 Products
ON DUPLICATE KEY UPDATE name=VALUES(name), image_url=VALUES(image_url);

-- 4. Seed 400 Product Listings (4 stores per product)
ON DUPLICATE KEY UPDATE price=VALUES(price), product_url=VALUES(product_url);

-- 5. Seed Price History Snapshots
ON DUPLICATE KEY UPDATE price=VALUES(price);
